      SUBROUTINE OPDEFC---- CONSTRUCT OPERATION ON PARAMETERSC-------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'STACK.CIN'      INCLUDE 'VARY.CIN'C-------------------------------------------------------------------      EQUIVALENCE     (FAKE,LAKE)C      IF (INDS .EQ. 0 .OR. INSERT) THEN        NWORD = 5        NDESC = 15        LAKE = 23        DATUM(1) = FAKE        IF (IOP(LEV) .LT. 10) THEN          LAKE = IVAL(LEV-1)          DATUM(2) = FAKE          VARY(2) = IREF(LEV-1)          LAKE = IVAL(LEV)          DATUM(3) = FAKE          VARY(3) = IREF(LEV)        ELSE          LAKE = IVAL(LEV)          DATUM(2) = FAKE          VARY(2) = IREF(LEV)          LAKE = 0          DATUM(3) = FAKE        ENDIF        LAKE = IOP(LEV)        DATUM(4) = FAKE        LEV = LEV - 1        LAKE = LEV        DATUM(5) = FAKE        CALL ELSTOR      ELSE        FLUSHL = .TRUE.        WRITE (NOUT,9001) 9001   FORMAT (' *** SORRY, OPERATIONS CANNOT BE INSERTED WITH ',     1          'INDICATOR 1 ***')        LEV = LEV - 1      ENDIF      IVAL(LEV) = LEV      IREF(LEV) = 0      IOPER = 1      IPDAT(IPARM) = 100C      RETURN                                                                  END